  sfence.vma
  LI(x14, (va_data >> 12) << 12)
  LA(x6, rvtest_data_1)
  slli x6, x6, 52
  srli x6, x6, 52
  add x14, x14, x6
  addi x13, x13, 16
  RVTEST_TSBI_GOTO_UMODE
  jalr ra, x14, 0
  RVTEST_TSBI_GOTO_SMODE
  PTE_SETUP_SV39(rvtest_slvl0_pg_tbl, (PTE_V), va_data, LEVEL1)
  LI(x15, 4096)
1:
  addi x15, x15, -1
  bnez x15, 1b
  LI(x9, 0)
  RVTEST_TSBI_GOTO_UMODE
